INSERT INTO events (thread_id, key, event_id, task_id, type, timestamp, raw_json, settled, received_at) VALUES ('99422fe0-da4d-4f86-a77d-f76f7bc32202', 'ccd90a13-7849-413b-8641-ab7e6bbe94be', 'ccd90a13-7849-413b-8641-ab7e6bbe94be', 'b7604daa-fcbd-455e-9c59-5ba5421c265c', 'response', 1793498895060, '{"id":"ccd90a13-7849-413b-8641-ab7e6bbe94be","type":"response","timestamp":1793498895060,"taskId":"b7604daa-fcbd-455e-9c59-5ba5421c265c","data":{"content":"","model":"gpt-6-luna","tools":[{"use":{"id":"exec-bf393556-338f-4cbb-8c80-c49b46802139","name":"Bash","type":"tool_use","input":{"command":"sed -n ''1,240p'' src/retry.ts && printf ''\\\\n--- tests ---\\\\n'' && sed -n ''1,260p'' src/retry.test.ts && printf ''\\\\n--- other src files ---\\\\n'' && for f in src/*.ts; do [ \\\"\"''$f\" = src/retry.ts ] || [ \"$f\" = src/retry.test.ts ] || { echo \"--- $f\"; sed -n ''\"''1,220p'' \\\"\"''$f\"; }; done"}},"result":{"type":"tool_result","content":"{\"type\":\"bash_output\",\"pending\":false,\"command\":\"sed -n ''1,240p'' src/retry.ts && printf ''\\\\\\\\n--- tests ---\\\\\\\\n'' && sed -n ''1,260p'' src/retry.test.ts && printf ''\\\\\\\\n--- other src files ---\\\\\\\\n'' && for f in src/*.ts; do [ \\\\\\\"\\\"''$f\\\" = src/retry.ts ] || [ \\\"$f\\\" = src/retry.test.ts ] || { echo \\\"--- $f\\\"; sed -n ''\\\"''1,220p'' \\\\\\\"\\\"''$f\\\"; }; done\",\"description\":\"\",\"content\":\"// Calls `fn` until it succeeds, doubling the wait after each failure, up to `maxMs`.\\n// Each wait is jittered to a random point between half and all of that step,\\n// so callers that fail together don''t retry together.\\nexport async function retry<T>(\\n  fn: () => Promise<T>,\\n  tries = 5,\\n  baseMs = 100,\\n  maxMs = 2000,\\n  onRetry?: (attempt: number, error: unknown, waitMs: number) => void,\\n): Promise<T> {\\n  let last: unknown;\\n  for (let i = 0; i < tries; i++) {\\n    try {\\n      return await fn();\\n    } catch (err) {\\n      last = err;\\n      if (i < tries - 1) {\\n        const waitMs = jitter(backoff(i, baseMs, maxMs));\\n        onRetry?.(i + 1, err, waitMs);\\n        await new Promise((r) => setTimeout(r, waitMs));\\n      }\\n    }\\n  }\\n  throw last instanceof Error ? last : new Error(String(last));\\n}\\n\\n/** The step before retry `attempt` (0 is the first retry): doubling from `baseMs`, capped at `maxMs`. */\\nexport function backoff(attempt: number, baseMs = 100, maxMs = 2000): number {\\n  return Math.min(baseMs * 2 ** attempt, maxMs);\\n}\\n\\n/** A wait somewhere between half and all of `step`. */\\nexport function jitter(step: number, random: () => number = Math.random): number {\\n  return step / 2 + random() * (step / 2);\\n}\\n\\n/** Every wait one caller makes when all `tries` fail (one fewer than the tries). */\\nexport function delays(tries = 5, baseMs = 100, maxMs = 2000, withJitter = true, random: () => number = Math.random): number[] {\\n  return Array.from({ length: Math.max(0, tries - 1) }, (_, i) => {\\n    const step = backoff(i, baseMs, maxMs);\\n    return withJitter ? jitter(step, random) : step;\\n  });\\n}\\n\\n--- tests ---\\nimport { test } from \\\"node:test\\\";\\nimport assert from \\\"node:assert/strict\\\";\\nimport { backoff, delays, retry } from \\\"./retry.js\\\";\\n\\ntest(\\\"returns the first success\\\", async () => {\\n  let calls = 0;\\n  const value = await retry(async () => {\\n    calls++;\\n    if (calls < 3) throw new Error(\\\"not yet\\\");\\n    return \\\"ok\\\";\\n  }, 5, 1);\\n  assert.equal(value, \\\"ok\\\");\\n  assert.equal(calls, 3);\\n});\\n\\ntest(\\\"gives up after the last try\\\", async () => {\\n  await assert.rejects(retry(async () => { throw new Error(\\\"always\\\"); }, 3, 1), /always/);\\n});\\n\\ntest(\\\"calls onRetry with the retry number, error, and wait before each retry\\\", async () => {\\n  let calls = 0;\\n  const retries: Array<[number, unknown, number]> = [];\\n  const errors = [new Error(\\\"first\\\"), new Error(\\\"second\\\")];\\n  const result = await retry(async () => {\\n    if (calls < errors.length) throw errors[calls++];\\n    return \\\"ok\\\";\\n  }, 3, 0, 0, (attempt, error, waitMs) => retries.push([attempt, error, waitMs]));\\n\\n  assert.equal(result, \\\"ok\\\");\\n  assert.deepEqual(retries, [[1, errors[0], 0], [2, errors[1], 0]]);\\n});\\n\\ntest(\\\"each step doubles up to the cap\\\", () => {\\n  assert.deepEqual([0, 1, 2, 3, 4, 5].map((i) => backoff(i, 100, 2000)), [100, 200, 400, 800, 1600, 2000]);\\n});\\n\\ntest(\\\"delays without jitter are the steps; with it, between half and all of each\\\", () => {\\n  assert.deepEqual(delays(5, 100, 2000, false), [100, 200, 400, 800]);\\n  assert.deepEqual(delays(5, 100, 2000, true, () => 0), [50, 100, 200, 400]);\\n  assert.deepEqual(delays(5, 100, 2000, true, () => 1), [100, 200, 400, 800]);\\n  assert.deepEqual(delays(1), []);\\n});\\n\\n--- other src files ---\\n--- src/app.ts\\n// The Retry visualizer page: several callers fail at the same moment and retry with the\\n// library''s own waits, drawn once without jitter and once with it.\\nimport { delays } from \\\"./retry.js\\\";\\n\\nconst SVG = \\\"http://www.w3.org/2000/svg\\\";\\nconst COLOURS = [\\\"#f37173\\\", \\\"#f6bc63\\\", \\\"#c2a7e2\\\", \\\"#e0555b\\\", \\\"#d99a3a\\\", \\\"#9d7cc8\\\", \\\"#f59597\\\", \\\"#f8cf8f\\\"];\\nconst WIDTH = 860;\\nconst LABEL = 76;\\nconst ROW = 26;\\nconst TRY = 8;\\n// Tries closer together than this land on the server at \\\"the same moment\\\".\\nconst BUSY_WINDOW_MS = 5;\\n\\nconst field = (id: string, min: number, max: number) => {\\n  const input = document.getElementById(id) as HTMLInputElement;\\n  const n = Math.round(Number(input.value));\\n  return Math.min(max, Math.max(min, Number.isFinite(n) ? n : min));\\n};\\n\\nfunction el(name: string, attrs: Record<string, string | number>, text?: string): SVGElement {\\n  const node = document.createElementNS(SVG, name);\\n  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, String(v));\\n  if (text !== undefined) node.textContent = text;\\n  return node;\\n}\\n\\n/** When each try happens: everyone tries at 0, then after each wait. */\\nfunction tries(waits: number[]): number[] {\\n  const at = [0];\\n  for (const w of waits) at.push(at[at.length - 1] + w);\\n  return at;\\n}\\n\\n/** The most callers retrying within BUSY_WINDOW_MS of each other (first tries left out). */\\nfunction busiest(rows: number[][]): number {\\n  const retries = rows.flatMap((r) => r.slice(1)).sort((a, b) => a - b);\\n  let best = 0;\\n  for (let i = 0, j = 0; j < retries.length; j++) {\\n    while (retries[j] - retries[i] > BUSY_WINDOW_MS) i++;\\n    best = Math.max(best, j - i + 1);\\n  }\\n  return best;\\n}\\n\\nfunction tick(span: number): number {\\n  for (const step of [50, 100, 250, 500, 1000, 2000, 5000, 10000, 20000]) if (span / step <= 8) return step;\\n  return 50000;\\n}\\n\\nfunction draw(svg: SVGSVGElement, rows: number[][], span: number) {\\n  const plot = WIDTH - LABEL - 12;\\n  const x = (ms: number) => LABEL + (ms / span) * plot;\\n  const height = rows.length * ROW + 28;\\n  svg.setAttribute(\\\"viewBox\\\", `0 0 ${WIDTH} ${height}`);\\n  svg.replaceChildren();\\n  const step = tick(span);\\n  for (let t = 0; t <= span; t += step) {\\n    svg.append(el(\\\"line\\\", { class: \\\"grid\\\", x1: x(t), x2: x(t), y1: 0, y2: rows.length * ROW }));\\n    const anchor = t === 0 ? \\\"start\\\" : x(t) > WIDTH - 40 ? \\\"end\\\" : \\\"middle\\\";\\n    svg.append(el(\\\"text\\\", { x: x(t), y: height - 8, \\\"text-anchor\\\": anchor }, `${t} ms`));\\n  }\\n  rows.forEach((at, r) => {\\n    const y = r * ROW + ROW / 2;\\n    const colour = COLOURS[r % COLOURS.length];\\n    svg.append(el(\\\"text\\\", { x: 0, y: y + 4 }, `caller ${r + 1}`));\\n    for (let k = 1; k < at.length; k++) {\\n      // The wait: a bar from one try to the next, a pixel short at each end.\\n      svg.append(el(\\\"rect\\\", { x: x(at[k - 1]) + TRY / 2 + 2, y: y - 5, width: Math.max(0, x(at[k]) - x(at[k - 1]) - TRY - 4), height: 10, fill: colour, \\\"shape-rendering\\\": \\\"crispEdges\\\" }));\\n    }\\n    for (const t of at) svg.append(el(\\\"rect\\\", { class: \\\"try\\\", x: x(t) - TRY / 2, y: y - TRY / 2, width: TRY, height: TRY, \\\"shape-rendering\\\": \\\"crispEdges\\\" }));\\n  });\\n}\\n\\nfunction stat(target: HTMLElement, rows: number[][]) {\\n  const n = rows.length;\\n  const peak = busiest(rows);\\n  const hot = peak > 1 && peak >= Math.max(2, Math.ceil(n * 0.6));\\n  // Everyone starts at 0, so the run lasts until the latest last try.\\n  const duration = Math.round(Math.max(...rows.map((at) => at[at.length - 1])));\\n  target.innerHTML = `Most at once: <strong class=\\\"${hot ? \\\"hot\\\" : \\\"\\\"}\\\">${peak} of ${n}</strong> callers retrying together; run takes <strong>${duration} ms</strong> from first try to last`;\\n}\\n\\nfunction run() {\\n  const n = field(\\\"tries\\\", 2, 8);\\n  const base = field(\\\"base\\\", 10, 2000);\\n  const max = Math.max(base, field(\\\"max\\\", 10, 10000));\\n  const callers = field(\\\"callers\\\", 1, 8);\\n  const plain = Array.from({ length: callers }, () => tries(delays(n, base, max, false)));\\n  const jittered = Array.from({ length: callers }, () => tries(delays(n, base, max, true)));\\n  // One scale for both, so the two pictures compare.\\n  const span = Math.max(...plain.flat(), ...jittered.flat(), 1);\\n  draw(document.getElementById(\\\"plain\\\") as unknown as SVGSVGElement, plain, span);\\n  draw(document.getElementById(\\\"jittered\\\") as unknown as SVGSVGElement, jittered, span);\\n  stat(document.getElementById(\\\"plain-stat\\\")!, plain);\\n  stat(document.getElementById(\\\"jittered-stat\\\")!, jittered);\\n}\\n\\ndocument.getElementById(\\\"controls\\\")!.addEventListener(\\\"submit\\\", (e) => {\\n  e.preventDefault();\\n  run();\\n});\\nfor (const input of document.querySelectorAll(\\\"#controls input\\\")) input.addEventListener(\\\"change\\\", run);\\nrun();\\n--- src/info.ts\\n// The `info` service: a small JSON answer saying where `web` is (another service''s\\n// publicURL, passed in by Flotilla) and what retry''s defaults wait.\\nimport { createServer } from \\\"node:http\\\";\\nimport { delays } from \\\"./retry.js\\\";\\n\\nconst port = Number(process.env.PORT ?? 8081);\\ncreateServer((_req, res) => {\\n  const body = { service: \\\"info\\\", web: process.env.WEB_URL ?? null, defaults: { tries: 5, baseMs: 100, maxMs: 2000 }, waitsWithoutJitter: delays(5, 100, 2000, false) };\\n  res.writeHead(200, { \\\"content-type\\\": \\\"application/json\\\" });\\n  res.end(JSON.stringify(body, null, 2) + \\\"\\\\n\\\");\\n}).listen(port, () => console.log(`info on :${port}; web is at ${process.env.WEB_URL ?? \\\"?\\\"}`));\\n\",\"error\":false}","is_error":false,"tool_use_id":"exec-bf393556-338f-4cbb-8c80-c49b46802139"}}],"is_reverted":false},"conversationId":"e1a0d3a5-1150-4fd0-b98e-1f94253b7951"}', 1, '2026-11-01T02:08:15.895Z');
