INSERT INTO events (thread_id, key, event_id, task_id, type, timestamp, raw_json, settled, received_at) VALUES ('99422fe0-da4d-4f86-a77d-f76f7bc32202', '4037f1c9-d857-4a50-b9f0-41b69ca820da', '4037f1c9-d857-4a50-b9f0-41b69ca820da', 'b7604daa-fcbd-455e-9c59-5ba5421c265c', 'response', 1793498896510, '{"id":"4037f1c9-d857-4a50-b9f0-41b69ca820da","type":"response","timestamp":1793498896510,"taskId":"b7604daa-fcbd-455e-9c59-5ba5421c265c","data":{"content":"- **Zero or negative `tries`:** No attempts are made, so `last` remains `undefined` and the function rejects with `Error(\"undefined\")`; this behavior isn’t tested.\n- **Non-`Error` rejection values:** The retry loop accepts any thrown value, but the final rejection converts non-`Error` values to `Error(String(value))`; tests only cover `Error` objects.\n- **`onRetry` callback throws:** If the callback throws, its error escapes immediately and prevents the scheduled wait and subsequent attempts; that behavior isn’t covered.","model":"gpt-6-luna","is_reverted":false},"conversationId":"e1a0d3a5-1150-4fd0-b98e-1f94253b7951"}', 1, '2026-11-01T02:08:17.494Z');
